CREATE OR REPLACE FUNCTION public.bizpage_status(p_workspace uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid;owner_id uuid;member_role text;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'not_signed_in' USING errcode='42501';END IF;
 SELECT id INTO actor FROM zoi.user_profiles WHERE auth_user_id=auth.uid();
 IF actor IS NULL THEN RAISE EXCEPTION 'no_access_to_workspace' USING errcode='42501';END IF;
 -- Match workspace→membership lock ordering used by organization authority writers.
 SELECT owner_profile_id INTO owner_id FROM zoi.workspaces WHERE id=p_workspace FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'no_access_to_workspace' USING errcode='42501';END IF;
 SELECT role INTO member_role FROM zoi.workspace_members WHERE workspace_id=p_workspace AND profile_id=actor FOR SHARE;
 IF owner_id IS DISTINCT FROM actor AND (member_role IS NULL OR member_role NOT IN('owner','admin','editor','viewer')) THEN
  RAISE EXCEPTION 'no_access_to_workspace' USING errcode='42501';
 END IF;
 -- Reuse the deployed current verified Auth/session guard after all authority waits.
 BEGIN PERFORM zoi.workspace_invitation_email();
 EXCEPTION WHEN insufficient_privilege THEN RAISE EXCEPTION 'verified_account_required' USING errcode='42501';END;
 RETURN jsonb_build_object('ok',true,'workspace_id',p_workspace,
  'owned',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',l.id,'name',l.name,'slug',l.slug,'city',l.city,'path',COALESCE(l.canonical_path,'/p/'||l.slug))) FROM zoi.listings l WHERE l.owner_workspace_id=p_workspace),'[]'::jsonb),
  'claims',COALESCE((SELECT jsonb_agg(jsonb_build_object('listing_id',c.listing_id,'status',c.claim_status,'name',l.name,'slug',l.slug,'submitted_at',c.submitted_at)) FROM zoi.listing_claims c JOIN zoi.listings l ON l.id=c.listing_id WHERE c.workspace_id=p_workspace),'[]'::jsonb));
END;$function$

CREATE OR REPLACE FUNCTION public.canonical_draft_context(p_workspace uuid, p_post uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ctx jsonb;kind text;
BEGIN
 PERFORM zoi.assert_workspace_write(p_workspace);
 SELECT context,'ai'INTO ctx,kind FROM zoi.ai_generation_draft_links WHERE workspace_id=p_workspace AND post_id=p_post;
 IF NOT FOUND THEN SELECT context,'editorial'INTO ctx,kind FROM zoi.editorial_draft_links WHERE workspace_id=p_workspace AND post_id=p_post;END IF;
 IF ctx?'listing'THEN PERFORM zoi.home_content_authorize(p_workspace,(ctx->>'listing')::uuid);END IF;
 PERFORM zoi.suite_current_session();RETURN jsonb_build_object('ok',true,'workspace',p_workspace,'post_id',p_post,'kind',kind,'context',ctx);
END$function$

CREATE OR REPLACE FUNCTION public.home_entity(p_slug text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare entity jsonb; published jsonb;
begin
 entity:=public.seo_entity(p_slug);
 if entity is null or entity->>'id' is null then return entity;end if;
 if not exists(select 1 from zoi.listings where id=(entity->>'id')::uuid and publish_status='published' and moderation_status in ('clean','cleared') and coalesce(marketplace_status,'')<>'hidden') then return null;end if;
 published:=public.home_design_public((entity->>'id')::uuid);
 return entity||jsonb_build_object('published_design',published);
end $function$

CREATE OR REPLACE FUNCTION public.social_save_post(p_workspace uuid, p_body text, p_channels text[] DEFAULT '{}'::text[], p_scheduled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_status text DEFAULT 'draft'::text, p_media jsonb DEFAULT '[]'::jsonb, p_nameday text DEFAULT NULL::text, p_meta jsonb DEFAULT '{}'::jsonb, p_id uuid DEFAULT NULL::uuid)
 RETURNS zoi.social_posts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'zoi', 'public'
AS $function$
DECLARE r zoi.social_posts; pid uuid;
BEGIN
  PERFORM zoi.assert_workspace_write(p_workspace);
  IF p_status NOT IN ('draft','scheduled') THEN p_status := 'draft'; END IF;
  SELECT up.id INTO pid FROM zoi.user_profiles up WHERE up.auth_user_id = auth.uid() LIMIT 1;
  IF p_id IS NOT NULL THEN
    UPDATE zoi.social_posts SET body=p_body, channels=p_channels, scheduled_at=p_scheduled_at, status=p_status,
      media=p_media, nameday_ref=p_nameday, meta=p_meta, updated_at=now()
    WHERE id=p_id AND workspace_id=p_workspace RETURNING * INTO r;
  ELSE
    INSERT INTO zoi.social_posts (workspace_id, author_profile, body, channels, scheduled_at, status, media, nameday_ref, meta)
    VALUES (p_workspace, pid, p_body, p_channels, p_scheduled_at, p_status, p_media, p_nameday, p_meta) RETURNING * INTO r;
  END IF;
  RETURN r;
END; $function$

CREATE OR REPLACE FUNCTION zoi.assert_workspace_write(p_workspace uuid, p_roles text[] DEFAULT ARRAY['owner'::text, 'admin'::text, 'editor'::text])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare r text;
begin r:=zoi.workspace_locked_role(p_workspace);
 if not coalesce(r=any(p_roles),false) then raise exception 'insufficient_permission' using errcode='42501';end if;
end $function$

CREATE OR REPLACE FUNCTION zoi.home_content_authorize(p_workspace uuid, p_listing uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=zoi.org_actor();owner_ws uuid;
BEGIN
 IF actor IS NULL THEN RAISE EXCEPTION 'not_authorized' USING errcode='42501';END IF;
 -- Verify the current account/session before any caller can return an old receipt.
 PERFORM zoi.workspace_invitation_email(false);
 PERFORM 1 FROM zoi.user_profiles WHERE id=actor FOR UPDATE;
 IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM zoi.user_profiles WHERE id=actor AND auth_user_id=auth.uid()) THEN RAISE EXCEPTION 'not_authorized' USING errcode='42501';END IF;
 -- The guard is VOLATILE and uses fresh statements after every existing lock wait.
 PERFORM zoi.workspace_invitation_email(false);
 PERFORM 1 FROM zoi.workspace_members WHERE workspace_id=p_workspace AND profile_id=actor AND role IN('owner','admin','editor')FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'not_authorized' USING errcode='42501';END IF;
 PERFORM zoi.workspace_invitation_email(false);
 SELECT owner_workspace_id INTO owner_ws FROM zoi.listings WHERE id=p_listing FOR UPDATE;
 IF NOT FOUND OR (owner_ws IS NOT NULL AND owner_ws<>p_workspace) OR NOT zoi.bizpage_can_edit(p_workspace,p_listing)THEN RAISE EXCEPTION 'no_access_to_listing' USING errcode='42501';END IF;
 PERFORM zoi.workspace_invitation_email(false);
 IF owner_ws IS NULL THEN PERFORM 1 FROM zoi.listing_claims WHERE listing_id=p_listing AND workspace_id=p_workspace AND claim_status IN('approved','verified')FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'no_access_to_listing' USING errcode='42501';END IF;
 PERFORM zoi.workspace_invitation_email(false);END IF;
 RETURN actor;
END $function$

CREATE OR REPLACE FUNCTION zoi.suite_current_session()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare sid text:=auth.jwt()->>'session_id';
begin
 if auth.uid() is null or coalesce(sid,'') !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then raise exception 'suite_session_unavailable' using errcode='42501';end if;
 perform 1 from auth.users where id=auth.uid() and deleted_at is null and coalesce(is_anonymous,false)=false and (banned_until is null or banned_until<=clock_timestamp());
 if not found then raise exception 'suite_session_unavailable' using errcode='42501';end if;
 perform 1 from auth.sessions where id=sid::uuid and user_id=auth.uid() and (not_after is null or not_after>clock_timestamp());
 if not found then raise exception 'suite_session_unavailable' using errcode='42501';end if;
end $function$
